// Client-Side Canvas WebP Image Compression Engine
const compressAndConvertToWebP = (file, maxWidth = 1000, quality = 0.82)=>{
    return new Promise((resolve)=>{
        if (!file.type.startsWith('image/')) {
            return resolve(file);
        }
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event)=>{
            const img = new Image();
            img.src = event.target?.result;
            img.onload = ()=>{
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;
                if (width > maxWidth) {
                    height = Math.round(height * maxWidth / width);
                    width = maxWidth;
                }
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);
                canvas.toBlob((blob)=>{
                    if (blob) {
                        const cleanName = file.name.substring(0, file.name.lastIndexOf('.')) || 'product';
                        const webpFileName = `${cleanName}_${Date.now()}.webp`;
                        const webpFile = new File([
                            blob
                        ], webpFileName, {
                            type: "image/webp"
                        });
                        resolve(webpFile);
                    } else {
                        resolve(file);
                    }
                }, "image/webp", quality);
            };
            img.onerror = ()=>resolve(file);
        };
        reader.onerror = ()=>resolve(file);
    });
};
